    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is NOT a required element for a valid informed consent?', '["Disclosure of risks and benefits", "Assessment of the patient''s decision-making capacity", "The patient''s agreement with the physician''s preferred choice", "Voluntariness (absence of coercion)"]', 2, 'Informed consent requires disclosure, capacity, comprehension, and voluntariness. The patient does NOT have to agree with the physician''s preferred choice; they have the right to choose an alternative or refuse entirely.'),
    (v_topic_id, 'A 14-year-old girl is asked to agree to a minor surgical procedure that her parents have already consented to. This agreement by the minor is known as:', '["Informed Consent", "Assent", "Proxy Consent", "Implied Consent"]', 1, 'Assent is the agreement of someone not yet legally old enough to provide informed consent (minors). While not legally binding like parental consent, it is ethically important to involve minors in their care.'),
    (v_topic_id, 'A patient is about to undergo an emergency appendectomy but is currently heavily sedated and cannot provide consent. No family is reachable. The surgeon proceeds. This is justified by:', '["Informed Consent", "Implied Consent in an Emergency", "Paternalism", "Justice"]', 1, 'In life-threatening emergencies where a patient cannot consent and delay would cause serious harm, consent is implied.'),
    (v_topic_id, 'What is the "Reasonable Patient Standard" for disclosure in informed consent?', '["The physician discloses what a ''typical'' physician in the community would disclose", "The physician discloses what a ''reasonable patient'' would want to know to make an informed decision", "The physician discloses every possible risk, no matter how rare", "The physician discloses only what the patient specifically asks about"]', 1, 'The ''reasonable patient'' standard (the modern legal standard in many jurisdictions) requires disclosing information that a typical patient would find significant in making their decision.'),
    (v_topic_id, 'A patient refuses a life-saving blood transfusion due to religious beliefs. The physician should first:', '["Get a court order to force the transfusion", "Assess the patient''s decision-making capacity", "Respect the refusal immediately without question", "Ask the family to overrule the patient"]', 1, 'Before accepting a refusal of life-saving care, the physician must ensure the patient has the capacity to understand the consequences of their decision.'),
    (v_topic_id, 'A 17-year-old "Emancipated Minor" seeks medical care. Which of the following is true regarding their ability to provide informed consent?', '["They still need parental consent for major surgeries", "They have the legal right to provide informed consent for themselves, just like an adult", "They can only consent to treatments for STIs or pregnancy", "They cannot provide consent until they turn 18"]', 1, 'Emancipated minors (e.g., married, in the military, or self-supporting/legally declared) have the same legal rights to consent as adults.'),
    (v_topic_id, 'Which of the following is a "Mature Minor" state in some jurisdictions?', '["A 5-year-old who is very smart", "A teenager who is deemed to have the maturity to understand the risks and benefits of a specific decision, even if not legally emancipated", "Any minor over the age of 16", "A minor with a chronic illness"]', 1, 'The "Mature Minor Doctrine" allows some older minors to make their own medical decisions if they are determined by a physician or court to have sufficient maturity.'),
    (v_topic_id, 'In most US states, a 16-year-old can provide consent for which of the following WITHOUT parental notification?', '["Treatment for a broken arm", "Treatment for a sexually transmitted infection (STI)", "A routine physical for sports", "Elective cosmetic surgery"]', 1, 'Most states have specific laws allowing minors to consent to sensitive services like STI testing/treatment, contraception, and prenatal care without parental consent.'),
    (v_topic_id, 'A patient signs a consent form but later admits they didn''t read it and don''t understand the risks. Is this valid informed consent?', '["Yes, the signature is legally binding", "No, because the ''comprehension'' element of informed consent is missing", "Yes, if the doctor told them it was a routine procedure", "No, unless a witness was present"]', 1, 'A signature on a form is evidence of consent, but not the process itself. If the patient does not understand the information, the consent is not ''informed''.'),
    (v_topic_id, 'A 30-year-old man refuses a life-saving surgery. He is currently intoxicated with alcohol. The physician should:', '["Respect his autonomy and let him leave", "Wait until he is sober to assess his capacity and obtain consent/refusal", "Perform the surgery immediately as he lacks capacity", "Call his boss"]', 1, 'Acute intoxication causes temporary incapacity. If the situation is an emergency, the physician acts under implied consent. If not an emergency, they should wait for the patient to clear.'),
    (v_topic_id, 'A patient asks: "If I were your mother, what would you do?" The physician answers based on their own personal values. This is potentially a violation of which element of informed consent?', '["Disclosure", "Voluntariness", "Capacity", "None, it is a helpful answer"]', 1, 'By injecting their personal bias, the physician may be inadvertently coercing or unduly influencing the patient''s decision (voluntariness).'),
    (v_topic_id, 'Which of the following is an example of "Undue Influence" in informed consent?', '["Explaining the risks of not having surgery", "Offering a patient a significant financial reward to participate in a risky clinical trial", "Providing a second opinion", "Showing the patient a video of the procedure"]', 1, 'Undue influence occurs when an incentive is so large that it compromises a person''s ability to make a truly voluntary choice.'),
    (v_topic_id, 'A patient with localized, treatable cancer refuses all treatment, preferring to ''let nature take its course.'' She clearly understands the diagnosis and that she will die without treatment. She is not depressed. The physician must:', '["Force treatment because the decision is ''irrational''", "Respect the refusal", "Request a psychiatric hold", "Ask the court to appoint a guardian"]', 1, 'A competent patient has the right to make ''irrational'' decisions (from the physician''s perspective) as long as they understand the consequences.'),
    (v_topic_id, 'When a minor refuses a life-saving treatment that their parents have consented to, the physician should:', '["Always follow the minor''s refusal", "Always follow the parents'' consent", "Work with the family and child to resolve the conflict, but ultimately the parents'' consent for life-saving care prevails unless the minor is emancipated", "Ignore the minor entirely"]', 2, 'While assent is sought, parents have the legal authority to consent to life-saving care for their non-emancipated children over the child''s objection.'),
    (v_topic_id, 'A physician fails to disclose a 1% risk of permanent nerve damage during a surgery. The complication occurs. The patient sues for lack of informed consent. In a "Physician-Based" standard jurisdiction, the patient must prove:', '["They would not have had the surgery if they knew the risk", "A reasonable physician would have disclosed that 1% risk", "The risk is common", "The doctor did it on purpose"]', 1, 'The physician-based standard (the older "Professional Standard") looks at what other competent physicians in the same field would have disclosed.'),
    (v_topic_id, 'A patient is told they have a "50% chance of survival" with surgery. Another patient is told they have a "50% chance of death." This is an example of:', '["Coercion", "Framing Effect", "Veracity", "Justice"]', 1, 'The "Framing Effect" describes how the way information is presented can significantly influence a person''s choice, even if the underlying facts are the same.'),
    (v_topic_id, 'Is informed consent required for a routine blood draw?', '["No, it is never required for simple tests", "Yes, but it is typically ''implied'' by the patient holding out their arm", "Only if the patient is a minor", "Only if the patient is in the hospital"]', 1, 'Implied consent is sufficient for low-risk, routine procedures where the patient''s actions clearly indicate agreement.'),
    (v_topic_id, 'A patient with a language barrier is asked to sign a consent form in English without a translator. This consent is:', '["Valid if the patient nodded", "Invalid due to lack of comprehension", "Valid if it was an emergency", "Valid if the nurse was present"]', 1, 'Meaningful informed consent requires that the information be provided in a language and at a level the patient can understand.'),
    (v_topic_id, 'The ''Therapeutic Exception'' to informed consent allows a physician to:', '["Withhold information that would cause the patient to refuse a necessary surgery", "Withhold information if disclosure would cause immediate and serious psychological harm to the patient", "Charge more for the procedure", "Skip the consent process if they are busy"]', 1, 'This is a very narrow and rarely used exception. It cannot be used just because the doctor thinks the patient will make a ''bad'' choice.'),
    (v_topic_id, 'Can a patient withdraw consent after a procedure has already begun?', '["No, once it starts, they must finish", "Yes, at any time, but only if it is safe to stop", "Only if they have a lawyer present", "Only if the doctor agrees"]', 1, 'Patients can withdraw consent at any time. If the procedure is mid-stream, the physician must stop as soon as it is medically safe to do so.'),
    (v_topic_id, 'A 16-year-old girl is pregnant and wants to keep the baby. Her parents want her to have an abortion. Who has the legal authority to make this decision?', '["The parents", "The 16-year-old", "The physician", "The court"]', 1, 'A pregnant minor generally has the authority to make decisions regarding her pregnancy, including whether to carry it to term. Parents cannot force a minor to have an abortion.'),
    (v_topic_id, 'In an emergency, if a patient''s "Wallet Card" or "Medical Alert Jewelry" states they are a Jehovah''s Witness and refuse blood, should the physician respect this?', '["No, only a signed legal document counts", "Yes, this provides clear evidence of the patient''s wishes even when they are unconscious", "Only if the family confirms it", "Only if it is notarized"]', 1, 'Reliable evidence of a patient''s prior refusal of treatment should be honored in an emergency.'),
    (v_topic_id, 'A patient is being asked to participate in a phase I clinical trial. The primary focus of disclosure should be:', '["The high likelihood of cure", "The potential risks and the fact that the primary goal is to test safety, not necessarily to provide benefit", "The financial compensation", "The names of other participants"]', 1, 'Phase I trials are about safety and dosing. Patients must understand that there may be no direct therapeutic benefit to them.'),
    (v_topic_id, 'Does a patient have the right to refuse to hear the risks of a procedure (i.e., "Waiver of Informed Consent")?', '["No, they must hear them to be safe", "Yes, a patient can choose to waive their right to be informed and ask the physician to decide", "Only if the family hears the risks instead", "Only in an emergency"]', 1, 'A patient can voluntarily waive their right to informed consent, though the physician should document this carefully.'),
    (v_topic_id, 'Which of the following is true regarding "Blanket" consent forms signed upon hospital admission?', '["They cover all major surgeries performed during the stay", "They generally only cover routine, low-risk care; specific informed consent is still needed for major procedures", "They are legally worthless", "They allow the hospital to share data with anyone"]', 1, 'Admission consent is for general care. Invasive or high-risk procedures require their own specific informed consent process.'),
    (v_topic_id, 'A patient is scheduled for a tubal ligation. The surgeon also decides to remove the patient''s appendix because it "looked a bit inflamed" during the surgery, without prior consent. This is:', '["Good clinical judgment", "A battery (illegal touching) and a violation of informed consent", "Justified by the principle of beneficence", "Standard practice"]', 1, 'Unless it was a life-threatening emergency, performing an additional, non-consented procedure is a violation of the patient''s autonomy and can be legally classified as battery.'),
    (v_topic_id, 'A patient with severe Alzheimer''s disease is refusing a hip replacement after a fall. His son, who is the Healthcare Proxy, wants the surgery to proceed. The physician should:', '["Always follow the patient''s refusal", "Follow the Healthcare Proxy''s decision, as the patient lacks decision-making capacity", "Do nothing", "Wait for the patient to get better"]', 1, 'When a patient lacks capacity, the designated surrogate (Healthcare Proxy) makes the decision based on the patient''s known values or best interests.'),
    (v_topic_id, 'Which of the following describes ''Substituted Judgment''?', '["The physician decides what they would want in the patient''s place", "The surrogate decides based on what they believe the patient would have wanted if they were competent", "The surrogate decides what is objectively ''best'' for the patient", "The court decides"]', 1, 'Substituted judgment is the preferred standard for surrogate decision-making, aiming to replicate the patient''s own autonomous choice.'),
    (v_topic_id, 'The ''Best Interests Standard'' for surrogate decision-making is used when:', '["The patient''s wishes are unknown and cannot be determined", "The patient is a minor", "Both A and B", "None of the above"]', 2, 'If a patient''s prior wishes are unknown (or if the patient was never competent, like a child), the surrogate must decide based on what would most benefit the patient.'),
    (v_topic_id, 'Can a 12-year-old child legally provide informed consent for an organ donation?', '["Yes, if the parents agree", "No, minors are generally prohibited from being organ donors except in very rare, specific court-ordered circumstances", "Only if it is for a sibling", "Only if they are emancipated"]', 1, 'Organ donation by minors is strictly regulated and generally not allowed due to the risk of coercion and the lack of direct benefit to the minor.'),
    (v_topic_id, 'A patient is unconscious and has no advance directive or appointed proxy. Who is typically the first person in the "Hierarchy of Surrogates" in most states?', '["The patient''s eldest child", "The patient''s spouse", "The patient''s parents", "The patient''s primary care doctor"]', 1, 'The standard hierarchy is: Spouse > Adult Children > Parents > Adult Siblings.'),
    (v_topic_id, 'A surrogate decision-maker refuses a life-saving treatment for an unconscious patient, but the physician suspects the surrogate is acting out of malice or financial gain. The physician should:', '["Follow the surrogate''s decision regardless", "Consult the hospital ethics committee or seek a court-appointed guardian", "Perform the treatment anyway", "Ignore the surrogate"]', 1, 'If a surrogate is clearly not acting in the patient''s best interest or following their known wishes, the physician has a duty to intervene.'),
    (v_topic_id, 'In research, "Coercion" is defined as:', '["Paying participants a fair wage for their time", "A credible threat of harm or loss of benefits to force participation", "Explaining the benefits of the study", "Providing free medical care as part of the study"]', 1, 'Coercion involves a threat, while "undue inducement" involves an excessive reward.'),
    (v_topic_id, 'A patient refuses to sign a consent form but says ''I want the surgery, just do it.'' The physician should:', '["Proceed without the signature", "Document the verbal consent and the reason for the refusal to sign, ideally with a witness", "Refuse to perform the surgery", "Wait for a lawyer"]', 1, 'The signature is not the consent; the conversation is. Documentation of the oral consent is key if the patient is physically unable or unwilling to sign.'),
    (v_topic_id, 'A 15-year-old boy refuses a life-saving appendectomy. His parents consent. The surgeon should:', '["Respect the boy''s refusal", "Perform the surgery based on parental consent", "Call the police", "None of the above"]', 1, 'For life-saving treatment, parental consent overrules a minor''s refusal.'),
    (v_topic_id, 'A patient asks: "What are the chances I will die?" The physician knows the risk is 5%, but says "It''s very safe, don''t worry." This is a failure of which element?', '["Disclosure", "Capacity", "Voluntariness", "None"]', 0, 'Providing misleading or incomplete information is a failure of the disclosure requirement.'),
    (v_topic_id, 'Which of the following is true about ''Opt-out'' consent (e.g., for HIV testing in some settings)?', '["It is illegal", "The patient is informed the test will be done unless they specifically refuse it", "The patient is not told about the test", "It is only for research"]', 1, 'Opt-out consent still requires notification, but it shifts the burden of action to the patient to refuse.'),
    (v_topic_id, 'A patient is participating in a clinical trial. They must be informed of:', '["The names of the researchers", "Any significant new findings during the study that might affect their willingness to continue", "The cost of the research equipment", "None of the above"]', 1, 'Ongoing informed consent is required in research.'),
    (v_topic_id, 'Can a physician perform a procedure on a patient who has been "Duly Committed" to a psychiatric hospital against their will?', '["Yes, for anything they need", "Only for psychiatric medications, but they still need consent for general medical procedures (unless it''s an emergency)", "Only if the patient agrees", "No, never"]', 1, 'Involuntary commitment for psychiatric care does not automatically mean the patient lacks capacity for all medical decisions.'),
    (v_topic_id, 'A patient with a terminal illness requests "Physician-Assisted Dying" in a state where it is legal. The physician has a moral objection. The physician:', '["Must perform it anyway", "Can refuse but should refer the patient to a willing provider", "Should try to talk the patient out of it", "Must report the patient"]', 1, 'Physicians generally have a right to conscientious objection but should not abandon the patient.'),
    (v_topic_id, 'A 16-year-old girl wants to start birth control. Her mother, who is present, says "No." In most US states, the physician should:', '["Follow the mother''s wishes", "Provide the birth control to the minor if she wants it, as she has the legal right to consent to contraception", "Tell them to come back when they agree", "Call the father"]', 1, 'Minors in most states can consent to their own contraceptive care without parental permission.'),
    (v_topic_id, 'The "Institutional Review Board" (IRB) is responsible for:', '["Reviewing the hospital''s budget", "Reviewing and approving the ethics of research involving human subjects", "Reviewing medical malpractice cases", "None of the above"]', 1, 'The IRB ensures that research follows ethical guidelines (like those in the Belmont Report).'),
    (v_topic_id, 'Which of the following is a key principle of the Belmont Report?', '["Paternalism", "Respect for Persons", "Fidelity", "Veracity"]', 1, 'The three principles are: Respect for Persons (Autonomy), Beneficence, and Justice.'),
    (v_topic_id, 'A patient is told that a procedure is "necessary" when there are actually several viable alternatives. This is a violation of:', '["Disclosure of Alternatives", "Justice", "Privacy", "None"]', 0, 'Informed consent requires disclosing reasonable alternatives to the proposed treatment.'),
    (v_topic_id, 'A patient is being treated for a "Placebo" in a study. They are told they have a "50% chance of receiving the active drug." This is:', '["Illegal", "Ethically permissible as long as the patient is informed of the randomization and the possibility of a placebo", "A violation of veracity", "A violation of justice"]', 1, 'Randomized controlled trials with placebos are ethical if there is "clinical equipoise" (uncertainty about which is better) and the patient is informed.'),
    (v_topic_id, 'A 5-year-old child is undergoing a painful blood draw. The child is screaming "No!". The parents and doctor proceed. This is:', '["A violation of the child''s autonomy", "Ethically permissible because the parents have consented to a necessary procedure", "Illegal", "Battery"]', 1, 'For young children, parents make the decision. The child''s dissent is noted, but medical necessity and parental consent override it.'),
    (v_topic_id, 'A patient asks to record their informed consent conversation on their phone. The physician should:', '["Refuse, as it is a violation of the physician''s privacy", "Allow it, as it can improve the patient''s comprehension and serve as a record of the process", "Call security", "Ask for a copy of the recording"]', 1, 'Allowing recordings is generally seen as supportive of patient autonomy and understanding.'),
    (v_topic_id, 'A physician provides a patient with a "Decision Aid" (e.g., a pamphlet or interactive tool) to help them choose between treatment options. This is a tool to improve:', '["Efficiency", "Comprehension in informed consent", "Profit", "Justice"]', 1, 'Decision aids help patients visualize the trade-offs between different choices.'),
    (v_topic_id, 'The "Common Rule" is:', '["A set of hospital rules for nurses", "A federal policy for the protection of human subjects in research", "A law about medical insurance", "None of the above"]', 1, 'The Common Rule is the baseline for IRB oversight of research in the US.'),
    (v_topic_id, 'A patient refuses a vaccine. The physician spends 20 minutes trying to "guilt" them into taking it by showing pictures of sick children. This is a violation of:', '["Disclosure", "Voluntariness (due to emotional coercion/manipulation)", "Justice", "Non-maleficence"]', 1, 'While education is good, using extreme emotional manipulation can compromise the voluntariness of the patient''s choice.');
